    @EventHandler( payloadType=CreateSecurityEvent.class )
    public void handle( CreateSecurityEvent event) {
	    LOGGER.info("handling CreateSecurityEvent - " + event );
	    Security entity = new Security();
            entity.setSecurityId( event.getSecurityId() );
            entity.setSymbol( event.getSymbol() );
            entity.setIsin( event.getIsin() );
            entity.setCusip( event.getCusip() );
            entity.setCurrency( event.getCurrency() );
            entity.setSecurityType( event.getSecurityType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllSecurity( entity );
    }

