    /**
     * Method to retrieve the Security via an SecurityPrimaryKey.
     * @param 	id Long
     * @return 	Security
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Security handle( FindSecurityQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getSecurityId() );
    }
    
    /**
     * Method to retrieve a collection of all Securitys
     *
     * @param	query	FindAllSecurityQuery 
     * @return 	List<Security> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Security> handle( FindAllSecurityQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindSecurity,
 * but only if the id matches
 *
 * @param		entity	Security
 */
	protected void emitFindSecurity( Security entity ) {
		LOGGER.info("handling emitFindSecurity" );
		
	    queryUpdateEmitter.emit(FindSecurityQuery.class,
	                            query -> query.getFilter().getSecurityId().equals(entity.getSecurityId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllSecurity
	 * 
	 * @param		entity	Security
	 */
	protected void emitFindAllSecurity( Security entity ) {
		LOGGER.info("handling emitFindAllSecurity" );
		
	    queryUpdateEmitter.emit(FindAllSecurityQuery.class,
	                            query -> true,
	                            entity);
	}

